export function groupByCategory(items) {
  return items.reduce((groups, item) => {
    const key = item.category;
    (groups[key] ??= []).push(item);
    return groups;
  }, {});
}

export function debounce(fn, delayMs) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delayMs);
  };
}

export function throttle(fn, intervalMs) {
  let last = 0;
  return (...args) => {
    const now = Date.now();
    if (now - last >= intervalMs) {
      last = now;
      fn(...args);
    }
  };
}

export function deepClone(value) {
  return JSON.parse(JSON.stringify(value));
}

export function flattenOne(arr) {
  return [].concat(...arr);
}

export function unique(arr) {
  return [...new Set(arr)];
}

export function pick(obj, keys) {
  return Object.fromEntries(
    keys.filter(k => k in obj).map(k => [k, obj[k]])
  );
}

export function omit(obj, keys) {
  const excluded = new Set(keys);
  return Object.fromEntries(
    Object.entries(obj).filter(([k]) => !excluded.has(k))
  );
}

export async function retry(fn, attempts) {
  for (let i = 0; i < attempts; i++) {
    try {
      return await fn();
    } catch (err) {
      if (i === attempts - 1) throw err;
    }
  }
}

export function paginate(arr, pageSize) {
  const pages = [];
  for (let i = 0; i < arr.length; i += pageSize)
    pages.push(arr.slice(i, i + pageSize));
  return pages;
}

export function camelToKebab(str) {
  return str.replace(/([A-Z])/g, m => `-${m.toLowerCase()}`);
}

export function parseQuery(search) {
  return Object.fromEntries(new URLSearchParams(search));
}

export function formatCurrency(amount, currency = 'USD', locale = 'en-US') {
  return new Intl.NumberFormat(locale, { style: 'currency', currency }).format(amount);
}

export function sortBy(arr, key, direction = 'asc') {
  const factor = direction === 'asc' ? 1 : -1;
  return [...arr].sort((a, b) => {
    if (a[key] < b[key]) return -1 * factor;
    if (a[key] > b[key]) return  1 * factor;
    return 0;
  });
}

export function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export function truncate(str, maxLength) {
  if (str.length <= maxLength) return str;
  return str.slice(0, maxLength).trimEnd() + '…';
}

export function intersection(a, b) {
  const set = new Set(b);
  return [...new Set(a)].filter(x => set.has(x));
}

export class EventEmitter {
  #listeners = new Map();

  on(event, fn) {
    (this.#listeners.get(event) ?? this.#listeners.set(event, new Set()).get(event)).add(fn);
    return this;
  }

  off(event, fn) {
    this.#listeners.get(event)?.delete(fn);
    return this;
  }

  emit(event, ...args) {
    this.#listeners.get(event)?.forEach(fn => fn(...args));
  }
}

export function titleCase(str) {
  return str.replace(/\b\w/g, c => c.toUpperCase());
}

export function clamp(value, min, max) {
  return Math.min(Math.max(value, min), max);
}
